import json
from pathlib import Path

root = Path(__file__).parent / 'translations/ro/full/chunks'
translations = {
    't000063': 'Căutarea vieții dincolo de Pământ ne pune, în cele din urmă, o oglindă în față. Ne provoacă să ne gândim ce face viața prețioasă și ce unește toate organismele vii, fie că există pe Pământ, fie pe o exoplanetă îndepărtată. Ne obligă să reconsiderăm lucrurile pe care le luăm de-a gata — aerul pe care îl respirăm, apa care ne susține — și să ne imaginăm un univers plin de viață, în forme familiare și stranii. Această reflecție ne adâncește aprecierea pentru fragilitatea și frumusețea vieții, stârnindu-ne totodată curiozitatea față de ceea ce s-ar mai putea afla acolo.',
    't000064': 'Dar ce se întâmplă dacă — și când — găsim viață dincolo de Pământ? Fie că descoperim viață microbiană pe Marte, o biosemnătură în atmosfera unei exoplanete îndepărtate sau chiar un semnal de la o civilizație extraterestră inteligentă, implicațiile vor fi copleșitoare.',
    't000065': 'La nivel științific, descoperirea vieții extraterestre ar revoluționa biologia, chimia și chiar fizica. Ar trebui să ne regândim înțelegerea originii și evoluției vieții. Este viața o inevitabilitate cosmică, apărând oriunde condițiile o permit, sau o anomalie rară și prețioasă? Răspunsurile la aceste întrebări ne-ar remodela nu doar cunoașterea științifică, ci și înțelegerea filosofică a existenței.',
    't000066': 'La nivel social, impactul ar fi la fel de profund. Așa cum am explorat în capitolele anterioare, descoperirea vieții în altă parte ar pune sub semnul întrebării presupuneri vechi despre unicitatea omenirii. Ne-ar obliga să înfruntăm posibilitatea ca Pământul să nu fie singurul leagăn al vieții și ca noi să nu fim cea mai avansată civilizație din univers. Cum am reacționa la o asemenea cunoaștere? Ne-ar uni ca specie, cultivând un sentiment de solidaritate cosmică? Sau ar semăna teamă și dezbinare, în timp ce ne-am confrunta cu necunoscutul?',
    't000067': 'Istoria oferă aici câteva repere. În fața necunoscutului, omenirea a răspuns adesea printr-un amestec de curiozitate și teamă. Explorarea Lumii Noi de către puterile europene, de exemplu, a fost împinsă atât de dorința descoperirii, cât și de teama de „celălalt”. Aceeași dinamică s-ar putea manifesta în căutarea vieții extraterestre. Dacă descoperim viață microbiană pe Marte sau Europa, reacția poate fi una de entuziasm științific; însă dacă întâlnim dovezi ale vieții inteligente, miza va fi mult mai mare.',
    't000068': 'Pregătirea noastră pentru o asemenea descoperire depinde nu doar de capacitățile tehnologice, ci și de capacitatea de adaptare. Suntem pregătiți să răspundem întrebărilor etice și filosofice pe care le-ar ridica? Ce drepturi ar avea viața extraterestră, mai ales dacă s-ar dovedi inteligentă? Cum am comunica cu civilizațiile extraterestre și ce le-am spune?',
    't000069': 'Poate cel mai important, cum ne-ar schimba descoperirea vieții în altă parte înțelegerea despre noi înșine? Dacă nu suntem singuri, ce înseamnă asta pentru viitorul omenirii? Ne-ar inspira să explorăm mai departe, să ne îndreptăm spre stele în căutarea unor noi legături? Sau ne-ar face să ne retragem în noi înșine, speriați de imensul necunoscut?',
    't000070': 'Aceste întrebări nu sunt doar ipotetice; sunt reale și presante. Pe măsură ce tehnologia avansează și explorarea cosmosului se adâncește, șansele de a găsi viață în altă parte cresc zi de zi. Fie că suntem pregătiți, fie că nu, universul ne-ar putea oferi curând răspunsuri la întrebări pe care ni le punem de milenii.',
    't000071': 'În cele din urmă, căutarea vieții dincolo de Pământ este o călătorie care poate nu se va încheia niciodată cu adevărat. Chiar dacă descoperim viață pe Marte sau Europa ori detectăm semnale de la o stea îndepărtată, universul este atât de vast și plin de posibilități, încât vor rămâne mereu mai multe de explorat, mai multe întrebări de pus și mai multe mistere de dezlegat.',
    't000072': 'Dar tocmai asta face călătoria atât de captivantă. Este o căutare nu doar a cunoașterii, ci și a sensului. Ne amintește că, într-un univers plin de stele și planete, fiecare reprezentând o nouă posibilitate, facem parte din ceva mult mai vast decât noi înșine. Indiferent dacă găsim viață, căutarea însăși reflectă cele mai profunde impulsuri umane: să explorăm, să înțelegem și să creăm legături.',
    't000073': 'Pe măsură ce continuăm această călătorie, trebuie să ne amintim că răspunsurile căutate s-ar putea să nu vină ușor sau repede. S-ar putea să nu vină nici în forma așteptată. Dar căutarea vieții dincolo de Pământ este, în ultimă instanță, o căutare a noastră — a locului nostru în univers, a scopului și a potențialului nostru. Iar cât timp continuăm să punem întrebări, călătoria merge mai departe, cu noi descoperiri și posibilități mereu la orizont.',
    't000074': 'Bibliografie',
}
for name in ('0013', '0014'):
    path = root / f'{name}.json'
    data = json.loads(path.read_text(encoding='utf-8'))
    for item in data['segments']:
        item['translation'] = translations.get(item['id'], item['source'])
    path.write_text(json.dumps(data, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
